import{_ as e,a as r,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse(`{"title":"List Returnable Items","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-returnable-items","title":"List Returnable Items","description":"List the return-eligible items of one of the authenticated customer's orders, with the quantity caps the store enforces.","query":"query ReturnableItems($orderId: Int!) {\\n  returnableItems(orderId: $orderId) {\\n    orderItemId\\n    productId\\n    sku\\n    name\\n    type\\n    urlKey\\n    price\\n    baseImageUrl\\n    qtyOrdered\\n    currentQuantity\\n    forReturnQuantity\\n    forCancelQuantity\\n    rmaQuantity\\n    rmaReturnPeriod\\n  }\\n}\\n","variables":"{\\n  \\"orderId\\": 45\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"returnableItems\\": [\\n      {\\n        \\"orderItemId\\": 78,\\n        \\"productId\\": 1,\\n        \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n        \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n        \\"type\\": \\"simple\\",\\n        \\"urlKey\\": \\"coastal-breeze-mens-blue-zipper-hoodie\\",\\n        \\"price\\": 100,\\n        \\"baseImageUrl\\": \\"https://example.com/storage/product/1/hoodie.webp\\",\\n        \\"qtyOrdered\\": 2,\\n        \\"currentQuantity\\": 2,\\n        \\"forReturnQuantity\\": 2,\\n        \\"forCancelQuantity\\": 0,\\n        \\"rmaQuantity\\": 0,\\n        \\"rmaReturnPeriod\\": 30\\n      }\\n    ]\\n  }\\n}\\n","commonErrors":[{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"NOT_FOUND","cause":"The order does not exist or is not owned by the authenticated customer","solution":"Only order IDs belonging to the logged-in customer can be queried"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/queries/list-returnable-items.md","filePath":"api/graphql-api/shop/returns/queries/list-returnable-items.md","lastUpdated":1787725411000}`),a={name:"api/graphql-api/shop/returns/queries/list-returnable-items.md"};function n(i,t,s,c,u,l){return d(),r("div",null,t[0]||(t[0]=[o('<h1 id="list-returnable-items" tabindex="-1">List Returnable Items <a class="header-anchor" href="#list-returnable-items" aria-label="Permalink to &quot;List Returnable Items&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>returnableItems</code> query lists the items of one of the customer&#39;s orders that are <strong>still eligible for return</strong> — within their return window and not already fully returned or canceled. Each row carries the trusted quantity caps the store enforces when a return is raised (<code>forReturnQuantity</code>, <code>forCancelQuantity</code>, <code>currentQuantity</code>), so a client can present the correct maximum. Use these rows to pick the <code>orderItemId</code> and quantity for <a href="/api/graphql-api/shop/returns/mutations/create-return.html"><code>createCustomerReturn</code></a>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This query requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Id of the order to list returnable items for. Must belong to the authenticated customer.</td></tr><tr><td><code>first</code></td><td><code>Int</code></td><td>❌ No</td><td>Number of items to return (forward pagination).</td></tr><tr><td><code>after</code></td><td><code>String</code></td><td>❌ No</td><td>Cursor for forward pagination. Use <code>endCursor</code> from a previous response.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><p>The query returns a plain list of items, not a cursor connection — there is no <code>edges</code>, <code>pageInfo</code>, or <code>totalCount</code> to select, and no pagination arguments. Every eligible item on the order comes back in one response.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderItemId</code></td><td><code>Int!</code></td><td>Id of the order item — use this when raising a return.</td></tr><tr><td><code>productId</code></td><td><code>Int!</code></td><td>Id of the product.</td></tr><tr><td><code>sku</code></td><td><code>String!</code></td><td>Product SKU.</td></tr><tr><td><code>name</code></td><td><code>String!</code></td><td>Product name.</td></tr><tr><td><code>type</code></td><td><code>String!</code></td><td>Product type, e.g. <code>simple</code>.</td></tr><tr><td><code>urlKey</code></td><td><code>String!</code></td><td>Product URL key.</td></tr><tr><td><code>price</code></td><td><code>Float!</code></td><td>Item price.</td></tr><tr><td><code>baseImageUrl</code></td><td><code>String</code></td><td>URL of the product&#39;s base image.</td></tr><tr><td><code>qtyOrdered</code></td><td><code>Int!</code></td><td>Quantity originally ordered.</td></tr><tr><td><code>currentQuantity</code></td><td><code>Int!</code></td><td>Quantity currently eligible to act on.</td></tr><tr><td><code>forReturnQuantity</code></td><td><code>Int!</code></td><td>Maximum units that can be returned.</td></tr><tr><td><code>forCancelQuantity</code></td><td><code>Int!</code></td><td>Maximum units that can be canceled.</td></tr><tr><td><code>rmaQuantity</code></td><td><code>Int!</code></td><td>Units already placed into a return.</td></tr><tr><td><code>rmaReturnPeriod</code></td><td><code>Int!</code></td><td>Return window in days.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/queries/list-return-reasons.html">List Return Reasons</a></li><li><a href="/api/graphql-api/shop/returns/mutations/create-return.html">Raise a Return</a></li><li><a href="/api/graphql-api/shop/returns/">Returns Overview</a></li></ul>',12)]))}const p=e(a,[["render",n]]);export{m as __pageData,p as default};
